/// This API allows the partner to retrieve a list of unsettled transactions (incl. Orders & Adjustments) generated by a seller, returning the detailed fee breakdown for a list of order ID and adjustment ID.  For now, this API only returns transactions which were created after 2025.01.01. Once one transaction is settled, which won't be returned by this API anymore, please get from Get Statement Transaction API.  **Pay attention to that all data returned through this API is an estimated amount which subject to change before settlement and can only used for seller's reference, final settlement amount per each transaction can only provided through statement related API.
pub async fn get_unsettled_transactions(configuration: &configuration::Configuration, sort_field: &str, page_token: Option<&str>, page_size: Option<i64>, sort_order: Option<&str>, search_time_ge: Option<i64>, search_time_lt: Option<i64>) -> Result<models::GetUnsettledTransactionsResponse, Error<GetUnsettledTransactionsError>> {
    // add a prefix to parameters to efficiently prevent name collisions
    let p_query_sort_field = sort_field;
    let p_query_page_token = page_token;
    let p_query_page_size = page_size;
    let p_query_sort_order = sort_order;
    let p_query_search_time_ge = search_time_ge;
    let p_query_search_time_lt = search_time_lt;

    let uri_str = format!("{}/finance/202507/orders/unsettled", configuration.base_path);
    let mut req_builder = configuration.client.request(reqwest::Method::GET, &uri_str);

    if let Some(ref param_value) = p_query_page_token {
        req_builder = req_builder.query(&[("page_token", &param_value.to_string())]);
    }
    if let Some(ref param_value) = p_query_page_size {
        req_builder = req_builder.query(&[("page_size", &param_value.to_string())]);
    }
    req_builder = req_builder.query(&[("sort_field", &p_query_sort_field.to_string())]);
    if let Some(ref param_value) = p_query_sort_order {
        req_builder = req_builder.query(&[("sort_order", &param_value.to_string())]);
    }
    if let Some(ref param_value) = p_query_search_time_ge {
        req_builder = req_builder.query(&[("search_time_ge", &param_value.to_string())]);
    }
    if let Some(ref param_value) = p_query_search_time_lt {
        req_builder = req_builder.query(&[("search_time_lt", &param_value.to_string())]);
    }
    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    if let Some(ref apikey) = configuration.api_key {
        let key = apikey.key.clone();
        let value = match apikey.prefix {
            Some(ref prefix) => format!("{} {}", prefix, key),
            None => key,
        };
        req_builder = req_builder.header("x-tts-access-token", value);
    };

    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;

    let status = resp.status();
    let content_type = resp
        .headers()
        .get("content-type")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("application/octet-stream");
    let content_type = super::ContentType::from(content_type);

    if !status.is_client_error() && !status.is_server_error() {
        let content = resp.text().await?;
        match content_type {
            ContentType::Json => serde_json::from_str(&content).map_err(Error::from),
            ContentType::Text => return Err(Error::from(serde_json::Error::custom("Received `text/plain` content type response that cannot be converted to `models::GetUnsettledTransactionsResponse`"))),
            ContentType::Unsupported(unknown_type) => return Err(Error::from(serde_json::Error::custom(format!("Received `{unknown_type}` content type response that cannot be converted to `models::GetUnsettledTransactionsResponse`")))),
        }
    } else {
        let content = resp.text().await?;
        let entity: Option<GetUnsettledTransactionsError> = serde_json::from_str(&content).ok();
        Err(Error::ResponseError(ResponseContent { status, content, entity }))
    }
}

